#include "CommandToEventAdapter.h"
CommandToEventAdapter::CommandToEventAdapter(CommandEventRegistry& r,EventSink& s,RuntimeIntegrationEventIdProvider& i):registry_(r),sink_(s),ids_(i),forwarded_(0U),ignored_(0U),failed_(0U),initialized_(false){}RuntimeIntegrationResult CommandToEventAdapter::begin(){for(size_t i=0U;i<registry_.size();++i)if(registry_.at(i)==nullptr||!registry_.at(i)->isValid())return RuntimeIntegrationResult::INTERNAL_ERROR;registry_.lock();initialized_=true;return RuntimeIntegrationResult::SUCCESS;}RuntimeIntegrationResult CommandToEventAdapter::finish(RuntimeIntegrationResult r){if(r==RuntimeIntegrationResult::SUCCESS)saturatingIncrement(forwarded_);else if(r==RuntimeIntegrationResult::IGNORED||r==RuntimeIntegrationResult::MAPPING_DISABLED)saturatingIncrement(ignored_);else if(r==RuntimeIntegrationResult::RETRY_LATER||r==RuntimeIntegrationResult::REJECTED||r==RuntimeIntegrationResult::FAILED||r==RuntimeIntegrationResult::INTERNAL_ERROR||r==RuntimeIntegrationResult::INVALID_INPUT)saturatingIncrement(failed_);return r;}bool CommandToEventAdapter::isInitialized()const{return initialized_;}
RuntimeIntegrationResult CommandToEventAdapter::onCommandResult(const CommandResult& result,uint32_t now){if(!initialized_)return finish(RuntimeIntegrationResult::NOT_INITIALIZED);if(!result.isValid())return finish(RuntimeIntegrationResult::INVALID_INPUT);const CommandEventMapping* m=registry_.find(result.status,result.errorCode);if(m==nullptr)return finish(RuntimeIntegrationResult::IGNORED);if(!m->enabled())return finish(RuntimeIntegrationResult::MAPPING_DISABLED);Event e;e.id=ids_.nextEventId();if(e.id==0U)return finish(RuntimeIntegrationResult::INTERNAL_ERROR);e.correlationId=result.requestId;e.type=m->eventType();e.severity=m->severity();e.sourceType=EventSourceType::COMMAND;e.sourceId=result.commandId;e.timestampMs=now;e.payload.value1=result.commandId;e.payload.value2=result.requestId;e.payload.signedValue=static_cast<int32_t>(result.errorCode);if(!e.isValid())return finish(RuntimeIntegrationResult::INTERNAL_ERROR);switch(sink_.publish(e)){case EventPublishResult::SUCCESS:return finish(RuntimeIntegrationResult::SUCCESS);case EventPublishResult::QUEUE_FULL:return finish(RuntimeIntegrationResult::RETRY_LATER);case EventPublishResult::INVALID_EVENT:case EventPublishResult::DUPLICATE_EVENT:return finish(RuntimeIntegrationResult::REJECTED);default:return finish(RuntimeIntegrationResult::INTERNAL_ERROR);}}
uint32_t CommandToEventAdapter::forwardedCount()const{return forwarded_;}uint32_t CommandToEventAdapter::ignoredCount()const{return ignored_;}uint32_t CommandToEventAdapter::failedCount()const{return failed_;}
